#include "political_shop_registry_detail.hpp"
namespace hanmo::resident {namespace {
Outcome<std::optional<PoliticalShopRegistryExecutionSource>> read(const PoliticalShopRegistryContext& x,const StableId& court_id,const StableId& boundary,std::optional<Integer> tick){
 auto checked=validate_political_shop_registry_successions(x);if(!checked.ok)return {false,{},checked.error};const auto& l=x.legal;const auto* court=l.catalog.courts.find(court_id);if(!court)return {false,{},common_failure("PoliticalShopRegistryCourtUnknown",court_id).error};
 Integer sequence=l.common.state().next_instance_id;if(!boundary.empty()){const auto* head=l.common.state().facts.find(boundary);if(!head)return {false,{},common_failure("PoliticalShopFactMismatch",boundary).error};auto n=shop_law_detail::fact_sequence(l.common,boundary,head->kind);if(!n.ok)return {false,{},n.error};sequence=n.value;
  // 原法律事实的载荷时刻由本账核；Commerce开设的时刻仍由其完整caller独立二验。
  std::optional<Integer> actual;const auto& s=l.state;if(auto p=s.registries.find(boundary))actual=p->tick;else if(auto p=s.warrants.find(boundary))actual=p->tick;else if(auto p=s.releases.find(boundary))actual=p->tick;else if(auto p=s.clearances.find(boundary))actual=p->tick;else if(auto p=s.permits.find(boundary))actual=p->tick;else if(auto p=s.revocations.find(boundary))actual=p->tick;
  StableId actual_court;if(auto p=s.registries.find(boundary))actual_court=p->court_id;else if(auto p=s.warrants.find(boundary))actual_court=p->court_id;else if(auto p=s.clearances.find(boundary))actual_court=p->court_id;else if(auto p=s.releases.find(boundary)){const auto* parent=s.warrants.find(p->warrant_fact_id);if(parent)actual_court=parent->court_id;}else if(auto p=s.permits.find(boundary)){const auto* parent=s.clearances.find(p->clearance_fact_id);if(parent)actual_court=parent->court_id;}else if(auto p=s.revocations.find(boundary)){const auto* permit=s.permits.find(p->permit_fact_id);const auto* parent=permit?s.clearances.find(permit->clearance_fact_id):nullptr;if(parent)actual_court=parent->court_id;}
  if(head->kind!="private_shop_opened"){if(actual_court!=court_id)return {false,{},common_failure("PoliticalShopRegistryBoundaryCourtMismatch",boundary).error};checked=validate_political_shop_licensing_fact_header(l.common,s,*head);if(!checked.ok)return {false,{},checked.error};if(actual!=tick)return {false,{},common_failure("PoliticalShopRegistryBoundaryTickMismatch",boundary).error};}
 }
 auto control=read_political_shop_registry_control(x.control,l.politics,l.politics_catalog,*court,boundary,tick);if(!control.ok)return {false,{},control.error};const auto* accepted=shop_registry_detail::latest(x,court_id,sequence);if(!accepted)return {true,std::nullopt,{}};const auto* policy=x.catalog.policies.find(accepted->policy_id);if(!policy)return {false,{},common_failure("PoliticalShopRegistryPolicyMismatch",accepted->id).error};auto endpoint=shop_registry_detail::endpoint(x,*policy);if(!endpoint.ok)return {false,{},endpoint.error};
 PoliticalShopRegistryExecutionSource result;result.source_identity=l.common.state().identity;result.endpoint=endpoint.value;result.acceptance_fact_id=accepted->id;result.initial_registry_fact_id=accepted->initial_registry_fact_id;result.policy_id=accepted->policy_id;result.previous_acceptance_fact_id=accepted->previous_acceptance_fact_id;result.registration_fact_id=accepted->registration_fact_id;result.approval_fact_id=accepted->approval_fact_id;result.occupation_fact_id=accepted->occupation_fact_id;result.accepting_authority=accepted->authority;result.accepting_grant_id=accepted->grant_id;result.accepted_tick=accepted->tick;result.observed_tick=control.value.observed_tick;
 result.registry_current=control.value.registration_fact_id==accepted->registration_fact_id&&control.value.organization_id==endpoint.value.organization_id;result.unavailable_code=result.registry_current?"":"PoliticalShopRegistryContinuityRequired";return {true,std::move(result),{}};
}
}
Outcome<std::optional<PoliticalShopRegistryExecutionSource>> PoliticalShopRegistryAccess::shop_registry_current(const StableId& court)const{return read(context_,court,{},std::nullopt);}
Outcome<std::optional<PoliticalShopRegistryExecutionSource>> PoliticalShopRegistryAccess::shop_registry_before_legal_fact(const StableId& court,const StableId& fact,Integer tick)const{return read(context_,court,fact,tick);}
}
